package org.xingmu.tv;
import android.app.Activity;import android.os.*;import android.content.*;import android.view.*;import android.webkit.*;import android.widget.*;import androidx.media3.common.*;import androidx.media3.exoplayer.*;import androidx.media3.ui.PlayerView;import java.util.*;
@androidx.annotation.OptIn(markerClass=androidx.media3.common.util.UnstableApi.class)
public final class PlayerActivity extends Activity {
 private final Handler handler=new Handler(Looper.getMainLooper());private final List<CatalogItem> items=new ArrayList<>();private int index,generation,retries;private ExoPlayer player;private PlayerView video;private WebView web;private TextView info;private FrameLayout screen;private boolean running;private View customView;private WebChromeClient.CustomViewCallback customCallback;private CatalogItem item;
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);TvUi.full(this);ArrayList<String> ids=getIntent().getStringArrayListExtra("ids");try{Map<String,CatalogItem> all=new HashMap<>();for(CatalogItem i:new CatalogRepository(this).load())all.put(i.id,i);if(ids!=null)for(String id:ids)if(all.containsKey(id))items.add(all.get(id));}catch(Exception e){TvUi.toast(this,"内容加载失败");}if(items.isEmpty()){finish();return;}index=Math.max(0,Math.min(state==null?getIntent().getIntExtra("index",0):state.getInt("index",0),items.size()-1));}
 @Override protected void onStart(){super.onStart();running=true;if(!items.isEmpty())open();}
 private void open(){release();generation++;retries=0;item=items.get(index);LinearLayout root=TvUi.col(this);root.setBackgroundColor(TvUi.BG);LinearLayout bar=TvUi.row(this);bar.setPadding(TvUi.dp(this,18),TvUi.dp(this,8),TvUi.dp(this,18),TvUi.dp(this,8));info=TvUi.text(this,item.title,16,TvUi.INK);bar.addView(info,new LinearLayout.LayoutParams(0,-2,1));Button prev=TvUi.button(this,"上一项"),next=TvUi.button(this,"下一项"),back=TvUi.button(this,"返回");prev.setOnClickListener(v->switchItem(-1));next.setOnClickListener(v->switchItem(1));back.setOnClickListener(v->finish());if(getResources().getConfiguration().screenWidthDp<600){for(Button button:new Button[]{prev,next,back}){button.setTextSize(13);button.setMinWidth(0);button.setMinimumWidth(0);button.setPadding(10,8,10,8);}}bar.addView(prev);bar.addView(next);bar.addView(back);root.addView(bar);screen=new FrameLayout(this);root.addView(screen,new LinearLayout.LayoutParams(-1,0,1));TextView attribution=TvUi.text(this,item.license+(item.live()?" · 左右键 / 频道键切换":""),12,TvUi.MUTED);attribution.setPadding(16,6,16,6);root.addView(attribution);setContentView(root);TvUi.full(this);
 if(item.mode.equals("official"))openWeb();else openVideo();
 }
 private void openVideo(){final int token=generation;video=new PlayerView(this);screen.addView(video,new FrameLayout.LayoutParams(-1,-1));video.setShowBuffering(PlayerView.SHOW_BUFFERING_WHEN_PLAYING);video.setControllerAutoShow(true);DefaultLoadControl buffers=new DefaultLoadControl.Builder().setBufferDurationsMs(15000,45000,1500,2500).build();player=new ExoPlayer.Builder(this).setLoadControl(buffers).build();video.setPlayer(player);player.addListener(new Player.Listener(){@Override public void onPlaybackStateChanged(int state){if(token!=generation)return;if(state==Player.STATE_READY){info.setText(item.title);retries=0;}}@Override public void onPlayerError(PlaybackException error){if(token!=generation||!running)return;if(item.live()&&retries<3){int delay=2000*(1<<retries++);info.setText("当前源暂时不可达，重试 "+retries+"/3…");handler.postDelayed(()->{if(token==generation&&running&&player!=null){player.prepare();player.play();}},delay);}else showError("播放失败，请检查来源或网络。没有绕过地区限制或付费授权。可返回设置更换已授权来源。");}});player.setMediaItem(MediaItem.fromUri(item.url));if(!item.live())player.seekTo(getPreferences(0).getLong("position_"+item.id,0));player.prepare();player.play();video.requestFocus();}
 private void openWeb(){try{web=new WebView(this);web.setBackgroundColor(0xff000000);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setUseWideViewPort(true);web.getSettings().setLoadWithOverviewMode(true);web.getSettings().setMediaPlaybackRequiresUserGesture(false);web.getSettings().setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.setWebChromeClient(new WebChromeClient(){@Override public void onShowCustomView(View view,CustomViewCallback callback){if(customView!=null){callback.onCustomViewHidden();return;}customView=view;customCallback=callback;((android.view.ViewGroup)getWindow().getDecorView()).addView(view,new android.view.ViewGroup.LayoutParams(-1,-1));TvUi.full(PlayerActivity.this);}@Override public void onHideCustomView(){hideWebFullscreen();}});web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,String url){return !CatalogParser.safeUrl(url);}@Override public void onReceivedError(WebView v,WebResourceRequest request,WebResourceError error){if(request.isForMainFrame())info.setText("官方页面不可达：请检查网络，或导入已授权直播流");}});screen.addView(web,new FrameLayout.LayoutParams(-1,-1));info.setText(item.title+" · 官方页面，可能需点击播放");web.loadUrl(item.url);web.requestFocus();}catch(RuntimeException e){showError("设备没有可用的 Android WebView，官方页面无法打开。请更新系统 WebView，或导入已授权的直接播放源。");}}
 private void showError(String message){TextView t=TvUi.text(this,message,19,TvUi.INK);t.setGravity(Gravity.CENTER);t.setPadding(36,24,36,24);screen.addView(t,new FrameLayout.LayoutParams(-1,-1));info.setText("播放暂不可用");}
 private void switchItem(int delta){index=CatalogParser.wrappedIndex(index,delta,items.size());open();}
 @Override public boolean dispatchKeyEvent(KeyEvent event){if(event.getAction()==KeyEvent.ACTION_DOWN&&item!=null){int key=event.getKeyCode();if(key==KeyEvent.KEYCODE_CHANNEL_UP||key==KeyEvent.KEYCODE_MEDIA_NEXT||(item.live()&&key==KeyEvent.KEYCODE_DPAD_RIGHT&&(video==null||!video.isControllerFullyVisible()))){switchItem(1);return true;}if(key==KeyEvent.KEYCODE_CHANNEL_DOWN||key==KeyEvent.KEYCODE_MEDIA_PREVIOUS||(item.live()&&key==KeyEvent.KEYCODE_DPAD_LEFT&&(video==null||!video.isControllerFullyVisible()))){switchItem(-1);return true;}if(key==KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE&&player!=null){if(player.isPlaying())player.pause();else player.play();return true;}}return super.dispatchKeyEvent(event);}
 private void hideWebFullscreen(){if(customView!=null){android.view.ViewParent parent=customView.getParent();if(parent instanceof android.view.ViewGroup)((android.view.ViewGroup)parent).removeView(customView);customView=null;WebChromeClient.CustomViewCallback callback=customCallback;customCallback=null;if(callback!=null)callback.onCustomViewHidden();}}
 @Override public void onBackPressed(){if(customView!=null)hideWebFullscreen();else super.onBackPressed();}
 private void release(){hideWebFullscreen();handler.removeCallbacksAndMessages(null);if(player!=null){if(item!=null&&!item.live())getPreferences(0).edit().putLong("position_"+item.id,player.getCurrentPosition()).apply();if(video!=null)video.setPlayer(null);player.release();player=null;}if(web!=null){web.stopLoading();web.loadUrl("about:blank");web.destroy();web=null;}video=null;}
 @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putInt("index",index);}
 @Override protected void onStop(){running=false;generation++;release();super.onStop();}
}
